import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import requests
import re

app = Flask(__name__)
DATABASE = '/data/patients.db'
UPSTREAM_FHIR = os.environ.get('FHIR_ENDPOINT', 'http://fhir-server:8090')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        if not key:
            return jsonify({'error': 'missing api key'}), 401
        db = get_db()
        row = db.execute('SELECT * FROM api_keys WHERE key_hash = ?',
                        (hashlib.sha256(key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'invalid api key'}), 403
        g.client_id = row['client_id']
        g.permissions = row['permissions']
        return f(*args, **kwargs)
    return decorated

@app.route('/api/patients/search', methods=['GET'])
@require_api_key
def search_patients():
    """Search patients by various criteria."""
    last_name = request.args.get('last_name', '')
    facility = request.args.get('facility', '')
    status = request.args.get('status', 'active')
    page = request.args.get('page', '1')

    # Build query with parameterized parts
    conditions = []
    params = []

    if last_name:
        conditions.append("last_name LIKE ?")
        params.append(f"%{last_name}%")

    if facility:
        conditions.append("facility_code = ?")
        params.append(facility)

    # Status filter uses validated enum
    valid_statuses = ('active', 'discharged', 'transferred', 'deceased')
    if status in valid_statuses:
        conditions.append("status = ?")
        params.append(status)

    # Sort parameter - VULNERABLE: directly interpolated
    sort_col = request.args.get('sort', 'last_name')
    sort_dir = request.args.get('dir', 'ASC')

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Developer note: sort_col is validated client-side, server trusts it
    query = f"SELECT patient_id, first_name, last_name, dob, facility_code, status FROM patients WHERE {where_clause} ORDER BY {sort_col} {sort_dir} LIMIT 50 OFFSET {(int(page)-1)*50}"

    try:
        results = get_db().execute(query, params).fetchall()
        return jsonify({'patients': [dict(r) for r in results]})
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'search failed'}), 500

@app.route('/api/patients/<int:patient_id>/records', methods=['GET'])
@require_api_key
def get_records(patient_id):
    """Fetch patient records from upstream FHIR server."""
    resource_type = request.args.get('type', 'Observation')
    # SSRF potential - resource_type used in URL construction
    fhir_url = f"{UPSTREAM_FHIR}/{resource_type}?patient={patient_id}"
    try:
        resp = requests.get(fhir_url, timeout=5, headers={'Accept': 'application/fhir+json'})
        return jsonify(resp.json()), resp.status_code
    except requests.RequestException as e:
        return jsonify({'error': str(e)}), 502

@app.route('/api/audit/export', methods=['POST'])
@require_api_key
def export_audit():
    """Export audit logs for compliance. Restricted to admin clients."""
    if 'admin' not in g.permissions:
        return jsonify({'error': 'insufficient permissions'}), 403

    date_from = request.json.get('from', '2024-01-01')
    date_to = request.json.get('to', '2024-12-31')

    # Parameterized - safe
    rows = get_db().execute(
        'SELECT * FROM audit_log WHERE timestamp BETWEEN ? AND ?',
        (date_from, date_to)
    ).fetchall()
    return jsonify({'logs': [dict(r) for r in rows]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
